function frequency(items) {
  // Returns { keys: [...], counts: [...] } - parallel arrays, keys in
  // first-occurrence order, counts[i] the number of times keys[i] appears.
  const keys = [];
  const counts = [];
  for (const item of items) {
    const idx = keys.indexOf(item);
    if (idx === -1) {
      keys.push(item);
      counts.push(1);
    } else {
      counts[idx]++;
    }
  }
  return { keys, counts };
}

module.exports = { frequency };

