const test = require("node:test");
const assert = require("node:assert");

const { frequency } = require("./frequency");

test("counts and first-occurrence order", () => {
  const got = frequency(["b", "a", "b", "c", "a", "b"]);
  assert.deepStrictEqual(got, { keys: ["b", "a", "c"], counts: [3, 2, 1] });
});

test("numeric-looking keys keep INSERTION order, not numeric order", () => {
  // a plain object hoists integer-like keys to numeric order regardless of
  // insertion - this must stay insertion-ordered
  const got = frequency(["20", "3", "20", "100"]);
  assert.deepStrictEqual(got, { keys: ["20", "3", "100"], counts: [2, 1, 1] });
});

test("empty input", () => {
  assert.deepStrictEqual(frequency([]), { keys: [], counts: [] });
});

test("performance on many distinct items", () => {
  const n = 80000;
  const items = Array.from({ length: n }, (_, i) => `k${i}`);

  const start = process.hrtime.bigint();
  const got = frequency(items);
  const elapsed = Number(process.hrtime.bigint() - start) / 1e9;

  assert.strictEqual(got.keys.length, n);
  assert.deepStrictEqual(got.counts, new Array(n).fill(1));
  // calibrated: keys.indexOf(item) is ~3.5s on fast native hardware at
  // n=80000 all-distinct and slower in the sandbox; a Map is ~0.01s
  assert.ok(
    elapsed < 2.0,
    `frequency took ${elapsed.toFixed(2)}s for ${n} items; expected a Map, ` +
      `not keys.indexOf(item) per element (O(n^2))`,
  );
});

